# Packs an install of BlitzLLVM (tools/build.cmake --install <dir>, the layout of the zips) as the two Linux downloads:
#   <out>/<name>.tar.gz              the files in one folder <name>/, to unpack anywhere (bin/blitzcc finds the rest next to it)
#   <out>/<name>-installer.sh        packaging/linux/installer.sh with that archive appended, which installs it (see its --help)
# Usage: make-packages.sh <install dir> <name> <out dir>
set -eu
dist="$1"; name="$2"; out="$3"
here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
mkdir -p "$out" "$work/$name"
cp -a "$dist/." "$work/$name/"
# Owner and group of the build machine mean nothing on another one.
tar -C "$work" --owner=0 --group=0 --numeric-owner -czf "$out/$name.tar.gz" "$name"
# The archive goes right after the marker line, which ends the script with a newline.
cat "$here/installer.sh" "$out/$name.tar.gz" > "$out/$name-installer.sh"
chmod +x "$out/$name-installer.sh"
ls -l "$out"
